<?php
if(!defined('ABSPATH'))exit;
class WP_FixPilot_AI_Repair {
 public static function settings(){return wp_parse_args((array)get_option('wp_fixpilot_ai_settings',array()),array('enabled'=>0,'endpoint'=>'https://api.openai.com/v1/responses','model'=>'gpt-5.6-terra','api_key'=>'','max_context_lines'=>120));}
 public static function propose($issue_id){$s=self::settings();if(empty($s['enabled'])||empty($s['api_key']))return new WP_Error('fixpilot_ai_disabled','AI Repair requires explicit opt-in and an API key.');global $wpdb;$i=$wpdb->get_row($wpdb->prepare("SELECT * FROM {$wpdb->prefix}fixpilot_issues WHERE id=%d",absint($issue_id)),ARRAY_A);if(!$i)return new WP_Error('fixpilot_ai_issue','Issue not found.');$safe=WP_FixPilot_Safety::can_edit_file($i['file']);if(is_wp_error($safe))return $safe;$ctx=self::context($i['file'],(int)$i['line'],(int)$s['max_context_lines']);if(is_wp_error($ctx))return $ctx;$prompt="You are generating a conservative WordPress PHP repair. Return ONLY JSON with keys explanation, confidence (0-100), replacements (array of {old,new}). Every old string must be an exact substring from the supplied code and each replacement must be minimal. Never change behavior beyond fixing the reported warning/deprecation. Do not add dependencies. Issue: ".$i['message']."\nPHP ".PHP_VERSION." WordPress ".get_bloginfo('version')." WooCommerce ".(defined('WC_VERSION')?WC_VERSION:'not active')."\nCODE:\n".$ctx;
  $body=array('model'=>$s['model'],'input'=>$prompt,'max_output_tokens'=>1800);$r=wp_remote_post(esc_url_raw($s['endpoint']),array('timeout'=>45,'headers'=>array('Authorization'=>'Bearer '.$s['api_key'],'Content-Type'=>'application/json'),'body'=>wp_json_encode($body)));if(is_wp_error($r))return $r;if((int)wp_remote_retrieve_response_code($r)>=300)return new WP_Error('fixpilot_ai_http','AI provider returned HTTP '.wp_remote_retrieve_response_code($r));$j=json_decode(wp_remote_retrieve_body($r),true);$text=self::extract_text($j);$text=trim($text);$text=preg_replace('/^```(?:json)?\s*|\s*```$/i','',$text);$proposal=json_decode(trim($text),true);if(!is_array($proposal)||empty($proposal['replacements']))return new WP_Error('fixpilot_ai_format','AI response was not a valid repair JSON proposal.');$proposal['issue_id']=(int)$issue_id;$proposal['file']=$i['file'];$proposal['created']=time();$proposal['hash']=hash('sha256',wp_json_encode($proposal));update_option('wp_fixpilot_ai_proposal',$proposal,false);return $proposal; }
 private static function extract_text($j){if(isset($j['output_text']))return (string)$j['output_text'];if(!empty($j['output'])&&is_array($j['output']))foreach($j['output'] as $o)if(!empty($o['content']))foreach($o['content'] as $c)if(isset($c['text']))return (string)$c['text'];return '';}
 private static function context($file,$line,$max){$code=@file($file);if(false===$code)return new WP_Error('fixpilot_ai_read','Could not read source file.');$half=max(20,(int)floor($max/2));$start=max(0,$line-1-$half);return implode('',array_slice($code,$start,$max));}
 public static function apply_saved(){ $p=(array)get_option('wp_fixpilot_ai_proposal',array());if(empty($p['file'])||empty($p['replacements']))return new WP_Error('fixpilot_ai_none','No AI proposal is saved.');$safe=WP_FixPilot_Safety::can_edit_file($p['file']);if(is_wp_error($safe))return $safe;$code=@file_get_contents($p['file']);if(false===$code)return new WP_Error('fixpilot_ai_read','Could not read source file.');$new=$code;foreach($p['replacements'] as $r){if(!isset($r['old'],$r['new'])||''===$r['old'])return new WP_Error('fixpilot_ai_replacement','Invalid replacement.');if(substr_count($new,$r['old'])!==1)return new WP_Error('fixpilot_ai_ambiguous','A proposed old fragment is not unique; refusing automatic apply.');$new=str_replace($r['old'],$r['new'],$new);}global $wpdb;$issue=$wpdb->get_row($wpdb->prepare("SELECT * FROM {$wpdb->prefix}fixpilot_issues WHERE id=%d",absint($p['issue_id'])),ARRAY_A);if(!$issue)return new WP_Error('fixpilot_ai_issue','Issue no longer exists.');$fix=array('type'=>'ai_proposal','confidence'=>isset($p['confidence'])?(int)$p['confidence']:0);if($fix['confidence']<85)return new WP_Error('fixpilot_ai_confidence','AI proposal confidence is below the 85% apply threshold.');return WP_FixPilot_Repair_Engine::commit($issue,$fix,$p['file'],$code,$new);}
}
